def max_skill_sum(n, a, b):
    from itertools import combinations

    # Step 1: Identify students who can work together calmly
    # Two students can work together calmly if there is no student who prefers over both.
    def can_work_together(x, y):
        # x prefers y if x knows some algorithm that y doesn't
        return (a[x] & a[y]) == (a[x] & (a[x] | a[y]))

    # Check all pairs to find the maximal subset of students who can work together
    max_sum = 0
    for size in range(2, n + 1):
        for group in combinations(range(n), size):
            can_work = True
            for i in range(len(group)):
                for j in range(i + 1, len(group)):
                    if not can_work_together(group[i], group[j]):
                        can_work = False
                        break
                if not can_work:
                    break
            if can_work:
                current_sum = sum(b[i] for i in group)
                max_sum = max(max_sum, current_sum)

    return max_sum

