def max_calm_group_sum(n, a, b):
    # Create a list of sets, where each set contains the algorithms known by each student
    known_algorithms = [set() for _ in range(n)]
    for i in range(n):
        for j in range(60):
            if a[i] & (1 << j):
                known_algorithms[i].add(j)

    # Create a graph where students are connected if they know different algorithms
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if known_algorithms[i] != known_algorithms[j]:
                graph[i].append(j)
                graph[j].append(i)

    # Find the maximum sum of b_i for a connected component
    def dfs(node, visited):
        visited[node] = True
        current_sum = b[node]
        for neighbor in graph[node]:
            if not visited[neighbor]:
                current_sum += dfs(neighbor, visited)
        return current_sum

    visited = [False] * n
    max_sum = 0
    for i in range(n):
        if not visited[i]:
            component_sum = dfs(i, visited)
            max_sum = max(max_sum, component_sum)

    return max_sum if max_sum > b[0] else 0

