def max_skill_sum(n, a, b):
    from itertools import combinations

    max_sum = 0

    # Generate all subsets of students
    for r in range(2, n + 1):
        for subset in combinations(range(n), r):
            # Check if the current subset forms a calm group
            is_calm_group = True
            for i in range(len(subset)):
                for j in range(len(subset)):
                    if i != j:
                        # Check if student i thinks they are better than student j
                        if (a[subset[i]] & ~a[subset[j]]) != 0:
                            break
                else:
                    continue
                is_calm_group = False
                break

            if is_calm_group:
                # Calculate the sum of skills in this calm group
                current_sum = sum(b[i] for i in subset)
                max_sum = max(max_sum, current_sum)

    return max_sum

