        current_sum = 0
        is_valid = True
        for i in range(n):
            if (a[i] & mask) == a[i]:  # i knows some of the same algorithms as mask
                current_sum += b[i]
                for j in range(60):
                    if (mask & (1 << j)) and not (a[i] & (1 << j)):
                        is_valid = False
                        break
                if not is_valid:
                    break
        if is_valid:
            max_sum = max(max_sum, current_sum)
    return max_sum

